CREATE TABLE discovery_profile_versions(revision INTEGER PRIMARY KEY, content TEXT NOT NULL CHECK(json_valid(content)), fingerprint TEXT NOT NULL, evaluation_fingerprint TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE discovery_control(id INTEGER PRIMARY KEY CHECK(id=1), revision INTEGER NOT NULL DEFAULT 0, schedule_revision INTEGER NOT NULL DEFAULT 0, enabled INTEGER NOT NULL DEFAULT 0, next_due_at INTEGER, evaluation_enabled INTEGER NOT NULL DEFAULT 0, evaluation_enabled_at INTEGER, evaluation_enabled_by TEXT, missed_count INTEGER NOT NULL DEFAULT 0, last_schedule_reason TEXT);
INSERT INTO discovery_control(id) VALUES(1);
CREATE TABLE discovery_runs(id TEXT PRIMARY KEY, request_key TEXT UNIQUE, revision INTEGER NOT NULL, trigger TEXT NOT NULL, snapshot TEXT NOT NULL, settings_snapshot TEXT NOT NULL, settings_revision INTEGER NOT NULL, status TEXT NOT NULL, attempt INTEGER NOT NULL DEFAULT 0, reason TEXT, counts TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, finished_at INTEGER, data_source TEXT NOT NULL);
CREATE UNIQUE INDEX discovery_one_active ON discovery_runs((1)) WHERE status IN ('QUEUED','RUNNING');
ALTER TABLE discovery_runs ADD COLUMN target_candidate_id INTEGER;
CREATE TABLE discovery_schedule_events(due_key TEXT PRIMARY KEY, due_at INTEGER NOT NULL, outcome TEXT NOT NULL, run_id TEXT);
CREATE TABLE discovery_repositories(repo_id INTEGER PRIMARY KEY, full_name TEXT NOT NULL, data TEXT NOT NULL, checked_at INTEGER NOT NULL);
CREATE TABLE discovery_candidates(issue_id INTEGER PRIMARY KEY, repo_id INTEGER NOT NULL REFERENCES discovery_repositories(repo_id), number INTEGER NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, content_hash TEXT NOT NULL, data TEXT NOT NULL, remote_state TEXT NOT NULL, visibility TEXT NOT NULL DEFAULT 'ACTIVE', favorite INTEGER NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 1, matched_revision INTEGER NOT NULL, preferred INTEGER NOT NULL, first_seen INTEGER NOT NULL, last_seen INTEGER NOT NULL, checked_at INTEGER, updated_at TEXT NOT NULL);
CREATE INDEX discovery_candidate_order ON discovery_candidates(visibility,favorite DESC,preferred DESC,updated_at DESC,issue_id);
CREATE TABLE discovery_sources(issue_id INTEGER NOT NULL REFERENCES discovery_candidates(issue_id), fingerprint TEXT NOT NULL, run_id TEXT NOT NULL, query_hash TEXT NOT NULL, summary TEXT NOT NULL, PRIMARY KEY(issue_id,fingerprint));
CREATE TABLE discovery_cursors(fingerprint TEXT NOT NULL, shard TEXT NOT NULL, watermark INTEGER, window_start INTEGER, window_end INTEGER, page INTEGER NOT NULL DEFAULT 0, reason TEXT, rotation INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(fingerprint,shard));
CREATE TABLE discovery_evaluations(id TEXT PRIMARY KEY, logical_key TEXT NOT NULL, attempt INTEGER NOT NULL DEFAULT 0, run_id TEXT NOT NULL, issue_id INTEGER NOT NULL, status TEXT NOT NULL, dispatch INTEGER NOT NULL DEFAULT 0, reserved_day TEXT NOT NULL, reserved_tokens INTEGER NOT NULL, actual_tokens INTEGER, usage_state TEXT NOT NULL DEFAULT 'RESERVED', content TEXT, error_code TEXT, started_at INTEGER NOT NULL, UNIQUE(logical_key,attempt));
CREATE INDEX discovery_evaluation_day ON discovery_evaluations(reserved_day);
CREATE TABLE github_request_budget(id INTEGER PRIMARY KEY AUTOINCREMENT, action_id TEXT NOT NULL, budget_day TEXT NOT NULL, resource TEXT NOT NULL, sent_at INTEGER NOT NULL, bytes INTEGER NOT NULL DEFAULT 0);
CREATE INDEX github_budget_day ON github_request_budget(budget_day,action_id);
CREATE TABLE github_cooldowns(resource TEXT PRIMARY KEY, not_before INTEGER NOT NULL, reason TEXT NOT NULL);
CREATE TABLE execution_queue(seq INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, entity_id TEXT NOT NULL, attempt INTEGER NOT NULL, state TEXT NOT NULL DEFAULT 'QUEUED', created_at INTEGER NOT NULL, UNIQUE(kind,entity_id,attempt));
CREATE INDEX execution_fifo ON execution_queue(state,seq);
CREATE TABLE candidate_analysis_links(id TEXT PRIMARY KEY, request_key TEXT NOT NULL UNIQUE, issue_id INTEGER NOT NULL, profile_revision INTEGER NOT NULL, status TEXT NOT NULL, task_id TEXT, version INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL);
CREATE TABLE source_rechecks(id TEXT PRIMARY KEY REFERENCES candidate_analysis_links(id), content TEXT, hash TEXT, confirmed_hash TEXT, confirmed_at INTEGER, checked_at INTEGER, status TEXT NOT NULL, error_code TEXT);
ALTER TABLE tasks ADD COLUMN source_selection_id TEXT;
ALTER TABLE tasks ADD COLUMN source_gate_status TEXT;
